mismatches=[]
for doc in docs_dir.glob('*.md'):
    mod = doc.stem
    text = doc.read_text()
    # parse table rows: | rule-XX | a | b | m |
    rows = re.findall(r'\|\s*(rule-\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|', text)
